  var b=O.benefits.find(function(x){return norm(x["Família de intervenção"])===norm(r.Intervencao)});
  if(!b){errors.push("Benefício não relacionado: "+r.Intervencao.slice(0,85));return;}
  r["Governança"]="Plano vigente";
  r["Classe de benefício"]=b["Classe de benefício"];
